import type { InferShape, Issue, SchemaNode, Shape } from "../schema";
import type { DbValue } from "./pg";

/** Turns one row's text values (model field order) into the row object. */
export type RowDecoder = (values: (string | null)[]) => unknown;

/** `createdAt` → `created_at`. */
export function snakeCase(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
}

/** A table and its columns at run time (one non-generic class; the row type lives in `Model`). */
export class ModelDef {
  /**
   * A typed decoder generated by `qala generate` (`.qala/models.gen.ts`). It builds the row with its
   * static shape, which scriptc compiles to fast native code; without it a generic decoder is used.
   */
  decoder: RowDecoder | null = null;
  /** Per field: does a NULL column become `undefined` (a bare `t.optional`) rather than `null`? */
  private readonly missingIsUndefined: boolean[] = [];

  constructor(
    readonly table: string,
    /** Field names in the app (camelCase). */
    readonly keys: string[],
    /** Column names in the database (snake_case), parallel to `keys`. */
    readonly columns: string[],
    /** Schema kind of each field (string, integer, boolean, datetime, ...), parallel to `keys`. */
    readonly kinds: string[],
    readonly fields: SchemaNode[],
    /** Field name of the primary key. */
    readonly primaryKey: string,
  ) {
    for (const field of fields) {
      const issues: Issue[] = [];
      field.check(null, "", issues, false);
      this.missingIsUndefined.push(field.optional && issues.length > 0);
    }
  }

  /** Index of a field name, or -1. */
  indexOf(key: string): number {
    return this.keys.indexOf(key);
  }

  columnOf(key: string): string {
    const i = this.keys.indexOf(key);
    if (i === -1) throw new Error(`${this.table}: unknown field "${key}" (fields: ${this.keys.join(", ")})`);
    return this.columns[i]!;
  }

  /** Installs a typed decoder: `values` are the row's columns in field order (`keys`). */
  useDecoder(fn: RowDecoder): void {
    this.decoder = fn;
  }

  /** One row's text values (field order) as the app row. */
  decodeValues(values: (string | null)[]): unknown {
    const typed = this.decoder;
    if (typed !== null) return typed(values);
    const out: Record<string, DbValue | undefined> = {};
    for (let i = 0; i < this.keys.length; i++) {
      const value = values[i];
      if (value === null || value === undefined) out[this.keys[i]!] = this.missingIsUndefined[i] === true ? undefined : null;
      else out[this.keys[i]!] = decodeValue(this.kinds[i]!, value);
    }
    return out;
  }
}

/** The typed view of a model: `Row` is the row type, `Key` the union of its field names. */
export type Model<Row, Key extends string = string> = ModelDef & { readonly __row?: () => Row; readonly __key?: () => Key };
/** The row type of a model. */
export type InferModel<M> = M extends { readonly __row?: () => infer R } ? R : never;

function decodeValue(kind: string, text: string): DbValue {
  if (kind === "integer" || kind === "number") return Number(text);
  if (kind === "boolean") return text === "t" || text === "true";
  if (kind === "datetime") return pgIso(text);
  return text;
}

/**
 * Postgres timestamptz text in UTC (the client sets `TimeZone=UTC`), e.g. "2026-11-15 08:00:00.123456+00",
 * as `Date#toISOString()` writes it ("2026-11-15T08:00:00.123Z"), with string operations only.
 * Any other format (offsets, dates, BC, 5-digit years) goes through `Date`.
 */
export function pgIso(text: string): string {
  const n = text.length;
  if (n >= 22 && text.charCodeAt(4) === 45 && text.charCodeAt(10) === 32 && text.charCodeAt(13) === 58 && text.charCodeAt(n - 3) === 43 && text.charCodeAt(n - 2) === 48 && text.charCodeAt(n - 1) === 48) {
    if (n === 22) return `${text.slice(0, 10)}T${text.slice(11, 19)}.000Z`;
    if (text.charCodeAt(19) === 46 && n >= 24 && n <= 29) {
      const frac = text.slice(20, n - 3);
      const ms = frac.length >= 3 ? frac.slice(0, 3) : frac.length === 2 ? `${frac}0` : `${frac}00`;
      return `${text.slice(0, 10)}T${text.slice(11, 19)}.${ms}Z`;
    }
  }
  return toIso(text);
}

/** Postgres timestamp text ("2026-11-15 12:00:00+04") → ISO-8601 through `Date` (any offset). */
export function toIso(text: string): string {
  let s = text.replace(" ", "T");
  if (s.length > 10 && /[+-]\d{2}$/.test(s)) s += ":00";
  const time = Date.parse(s);
  return Number.isNaN(time) ? text : new Date(time).toISOString();
}

export type ModelOptions = { primaryKey?: string };

/**
 * Declares a table:
 *
 *   export const Task = model("tasks", { id: t.uuid(), title: t.string(), done: t.boolean(), createdAt: t.datetime() });
 *   export type Task = InferModel<typeof Task>;
 *
 * Field names are camelCase in code and snake_case in the database.
 */
export function model<const S extends Shape>(table: string, shape: S, options: ModelOptions = {}): Model<InferShape<S>, Extract<keyof S, string>> {
  const keys = Object.keys(shape);
  const columns: string[] = [];
  const kinds: string[] = [];
  const fields: SchemaNode[] = [];
  for (const key of keys) {
    const field = shape[key]!;
    columns.push(snakeCase(key));
    kinds.push(field.kind);
    fields.push(field);
  }
  const primaryKey = options.primaryKey ?? "id";
  if (!keys.includes(primaryKey)) throw new Error(`model("${table}"): primary key "${primaryKey}" is not a field`);
  return new ModelDef(table, keys, columns, kinds, fields, primaryKey);
}
